import common as C
p=C.WS/'config.json';cfg=C.json.loads(p.read_text())
cfg['premeasurement_addendum']=dict(reason='Single MAST search returns no TESS-SPOC/QLP LC for s25,40,50,52',timestamp=C.datetime.datetime.now(C.datetime.timezone.utc).isoformat(),missing_spoc='Use native TESScut target-time correction if TIME/TIMECORR allow it; no optimal aperture claim. Central 3x3 is raw fallback. No CROWDSAP is known; never use these sectors to exclude a period. Show their per-epoch native depths, controls and injections; SAP-only likelihood/rejection therefore has explicitly incomplete coverage. Period cannot receive RAW_SIGNAL_CONSISTENT with these uncalibrated dilution gaps.')
C.write(p,cfg)
with open(C.WS/'PLAN.md','a',encoding='utf-8') as f:f.write('\n## Premeasurement addendum: missing pipeline light curves\nThe single MAST search found no TESS-SPOC or QLP light curve in sectors 25, 40, 50, 52. Acquire their cubes to establish coverage and measure central 3x3 photometry. An absent SPOC optimal aperture stays unavailable. Retain the documented TESScut BTJD times when target timing cannot be independently matched, and state this limitation. No CROWDSAP is known for these fallback curves: show depths and predicted-epoch diagnostics, but do not use them to exclude an alias. The joint likelihood uses SAP where available. RAW_SIGNAL_CONSISTENT cannot be assigned while these coverage/dilution gaps remain. This addendum precedes all new depth measurements.\n')
C.write(C.WS/'inputs/premeasurement_addendum_seal.json',dict(utc=cfg['premeasurement_addendum']['timestamp'],config_sha256=C.sha(p),plan_sha256=C.sha(C.WS/'PLAN.md'),depths_measured=False))
print('Missing-input handling recorded before depths')
